package com.example.vitality.ui.goal;
import android.os.Bundle;import android.view.View;import android.widget.*;import androidx.appcompat.app.AlertDialog;import java.util.*;import com.example.vitality.R;import com.example.vitality.ui.main.PageFragment;import com.example.vitality.data.entity.*;import com.example.vitality.utils.*;
public class GoalsFragment extends PageFragment {
 private long day=Formats.dayStart(System.currentTimeMillis());
 @Override public void onViewCreated(View v,Bundle state){if(state!=null)day=state.getLong("day",day);heading("Mục tiêu của bạn","Từng việc nhỏ hôm nay, tiến gần hơn tới mục tiêu");observeAll(this::render,vm.goals,vm.journals,vm.measurements);}
 private void render(){clear();String[] categories={"Cơ thể","Ăn uống & nước","Vận động","Giấc ngủ"};
 for(int i=0;i<categories.length;i++){final int category=i;button("+ "+categories[i],()->{Bundle args=new Bundle();args.putInt("category",category);androidx.navigation.fragment.NavHostFragment.findNavController(this).navigate(R.id.goalEditor,args);});}
 button("Ngày đang xem: "+Formats.day(day),()->{Calendar c=Calendar.getInstance();c.setTimeInMillis(day);android.app.DatePickerDialog d=new android.app.DatePickerDialog(requireContext(),(view,y,m,dd)->{Calendar selected=Calendar.getInstance();selected.set(y,m,dd,0,0,0);day=Formats.dayStart(selected.getTimeInMillis());render();},c.get(Calendar.YEAR),c.get(Calendar.MONTH),c.get(Calendar.DAY_OF_MONTH));d.getDatePicker().setMaxDate(System.currentTimeMillis());d.show();});
 List<Goal> goals=vm.goals.getValue();if(goals==null||goals.isEmpty()){text("Chưa có mục tiêu. Đặt cân nặng/vòng eo mong muốn, món muốn ăn hoặc số phút chạy bộ mỗi ngày.");return;}
 card("HẰNG NGÀY","Tiến độ ngày "+Formats.day(day),null,null);int total=GoalProgress.daily(goals,vm.journals.getValue(),vm.measurements.getValue(),day);text(total+"% hoàn thành");bar(total);text("Mỗi mục tiêu hằng ngày có trọng số bằng nhau. Thanh tự cập nhật khi bạn ghi hoặc xóa nhật ký; sang ngày mới tính lại từ 0.").setTextSize(12);endCard();
 List<Goal> ordered=new ArrayList<>(goals);ordered.sort(java.util.Comparator.comparingInt(GoalProgress::category));int lastCategory=-1;
 for(Goal g:ordered){boolean body=GoalProgress.body(g);if(!body&&Formats.dayStart(g.createdAt)>day)continue;int group=GoalProgress.category(g);if(group!=lastCategory){text(categories[group]).setTextSize(22);lastCategory=group;}double value=GoalProgress.current(g,vm.journals.getValue(),vm.measurements.getValue(),day);int pct=GoalProgress.percent(g,value);card(body?"CƠ THỂ · SỐ ĐO MỚI NHẤT":"MỖI NGÀY",g.title,"Xóa",()->new AlertDialog.Builder(requireContext()).setTitle("Xóa mục tiêu?").setMessage("Nhật ký và số đo vẫn được giữ. Mục tiêu này sẽ không còn xuất hiện khi xem các ngày trước.").setNegativeButton("Hủy",null).setPositiveButton("Xóa",(d,w)->vm.run(()->vm.goalRepo.delete(g),true)).show());
 text(Formats.number(value)+" / "+Formats.number(g.target)+" "+GoalProgress.unit(g)+"  ·  "+pct+"%");bar(pct);if(body)text("Bắt đầu: "+Formats.number(g.baseline)+" "+GoalProgress.unit(g)+" · "+Formats.day(g.createdAt));if(g.keyword!=null&&!g.keyword.trim().isEmpty())text("Tự tính nhật ký có tên chứa: “"+g.keyword+"”").setTextSize(12);text(pct>=100?"✓ Đã đạt mục tiêu":"Đang thực hiện");
 if(body)button("Cập nhật số đo",()->editor(0));else if(day==Formats.dayStart(System.currentTimeMillis()))button("Ghi nhận để tăng tiến độ",()->{if(g.kind.equals("water")){com.example.vitality.ui.diary.JournalEditorDialog.create("water",0).show(getParentFragmentManager(),"water_entry");}else navigate(g.kind.equals("nutrition")?R.id.nutrition:g.kind.equals("sleep")?R.id.sleep:R.id.activity);});endCard();}
 }
 private void bar(int pct){ProgressBar bar=widget(R.layout.widget_goal_progress);bar.setProgress(pct);bar.setContentDescription("Hoàn thành "+pct+" phần trăm");}
 @Override public void onSaveInstanceState(Bundle b){super.onSaveInstanceState(b);b.putLong("day",day);}
}
